import collections

class Solution:
    def firstUniqChar(self, s: str) -> int:
        # First pass: Build the frequency map in O(N) time
        # collections.Counter perfectly handles the counting phase
        counts = collections.Counter(s)

        # Second pass: Find the first character with a count of 1
        for i, char in enumerate(s):
            if counts[char] == 1:
                return i

        # Return -1 if no unique character exists
        return -1

import math

class Solution:
    def gcdOfStrings(self, str1: str, str2: str) -> str:
        # Step 1: Verify if they share a common building block
        if str1 + str2 != str2 + str1:
            return ""

        # Step 2: Find the GCD of their lengths
        gcd_length = math.gcd(len(str1), len(str2))

        # Step 3: Return the common building block prefix
        return str1[:gcd_length]

import collections

class Solution:
    def maxFreq(self, s: str, maxLetters: int, minSize: int, maxSize: int) -> int:
        freq_map = collections.defaultdict(int)
        max_freq = 0

        # We ONLY need to check windows of length exactly 'minSize'
        for i in range(len(s) - minSize + 1):
            sub = s[i:i + minSize]

            # If the number of unique characters is within the limit
            if len(set(sub)) <= maxLetters:
                freq_map[sub] += 1

                # Keep track of the maximum frequency seen so far
                if freq_map[sub] > max_freq:
                    max_freq = freq_map[sub]

        return max_freq

class Solution:
    def removeDuplicates(self, s: str, k: int) -> str:
        # Stack stores pairs of [character, frequency]
        stack = []

        for char in s:
            if stack and stack[-1][0] == char:
                stack[-1][1] += 1
            else:
                stack.append([char, 1])

            # If the top group reaches exactly size k, remove it
            if stack[-1][1] == k:
                stack.pop()

        # Reconstruct the final string from the stack
        return "".join(char * count for char, count in stack)

import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    s = list(input_data[0])
    n = len(s)

    started = False
    for i in range(n):
        # Find the first non-'a' character to start the greedy shift
        if s[i] != 'a':
            started = True
            s[i] = chr(ord(s[i]) - 1)
        # If we have already started shifting and hit an 'a', we must stop
        elif started:
            break

    # Trap: If the string was entirely 'a's, we MUST do exactly one shift
    if not started:
        s[-1] = 'z'

    print("".join(s))

if __name__ == '__main__':
    solve()
